use core.files as files
use core.process as process
use core.text as text

struct Entry {
    key: String
    value: String
    active: Bool
}

fn run() {
    path :: process.argv().get(1) ?? panic("missing path")
    source :: files.read(path) ?? panic("read failed")
    entries := [Entry]{}

    loop line in source.lines() {
        if line.trim().is_empty() -> next
        parts :: text.splitn(~line, "|", 3)
        if parts.len() != 3 -> panic("malformed journal record")
        kind :: parts.get(0) ?? panic("malformed journal record")
        key :: parts.get(1) ?? panic("malformed journal record")
        value :: parts.get(2) ?? panic("malformed journal record")
        if key.is_empty() -> panic("empty journal key")

        if kind == "put" {
            updated := false
            loop i in 0..<entries.len() {
                if entries[i].active && entries[i].key == key {
                    entries[i].value = ~value
                    updated = true
                    break
                }
            }
            if !updated -> entries.push(Entry{key: ~key, value: value, active: true})
            next
        }
        if kind == "delete" {
            if value != "" -> panic("delete record must have empty value")
            loop i in 0..<entries.len() {
                if entries[i].active && entries[i].key == key {
                    entries[i].active = false
                    break
                }
            }
            next
        }
        panic("unknown journal record {kind}")
    }

    loop entry in entries {
        if entry.active -> print("{entry.key}={entry.value}")
    }
}
